def filterCharactersByFrequency(s: str, k: int) -> str:
    # 1. Count frequency for each character
    freq = {}
    for ch in s:
        if ch not in freq:
            freq[ch] = 0
        freq[ch] += 1

    # 2. Build the result by keeping chars with freq ≥ k, in original order
    result = []
    for ch in s:
        if freq[ch] >= k:
            result.append(ch)

    # 3. Join and return result
    return ''.join(result)
